export class LedgerClient {
  #opened = 0;
  constructor(options = {}) {
    this.title = String(options.title ?? "untitled");
  }
  async entry(key, options) {
    this.#opened++;
    return { key: String(key), extra: options === undefined ? 0 : Object.keys(options).length, opened: this.#opened };
  }
  async close() {
    return this.#opened;
  }
}
